using Marina.Application.Abstractions; using Marina.Domain.Catalog; using Marina.Domain.Commerce; using Marina.Domain.Security; using Marina.Persistence.Identity; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Identity.EntityFrameworkCore; using Microsoft.EntityFrameworkCore;
namespace Marina.Persistence.Data;
public sealed class MarinaDbContext(DbContextOptions<MarinaDbContext> options):IdentityDbContext<AppUser,IdentityRole<Guid>,Guid>(options),IApplicationDbContext {
 public DbSet<Category> Categories=>Set<Category>(); public DbSet<CategoryTranslation> CategoryTranslations=>Set<CategoryTranslation>(); public DbSet<Brand> Brands=>Set<Brand>(); public DbSet<BrandTranslation> BrandTranslations=>Set<BrandTranslation>(); public DbSet<Product> Products=>Set<Product>(); public DbSet<ProductTranslation> ProductTranslations=>Set<ProductTranslation>(); public DbSet<ProductVariant> ProductVariants=>Set<ProductVariant>(); public DbSet<ProductImage> ProductImages=>Set<ProductImage>(); public DbSet<ColorOption> Colors=>Set<ColorOption>(); public DbSet<ColorTranslation> ColorTranslations=>Set<ColorTranslation>(); public DbSet<SizeOption> Sizes=>Set<SizeOption>(); public DbSet<SizeTranslation> SizeTranslations=>Set<SizeTranslation>(); public DbSet<Inventory> Inventories=>Set<Inventory>(); public DbSet<Cart> Carts=>Set<Cart>(); public DbSet<CartItem> CartItems=>Set<CartItem>(); public DbSet<Address> Addresses=>Set<Address>(); public DbSet<Favorite> Favorites=>Set<Favorite>(); public DbSet<Coupon> Coupons=>Set<Coupon>(); public DbSet<CouponUsage> CouponUsages=>Set<CouponUsage>(); public DbSet<Order> Orders=>Set<Order>(); public DbSet<OrderItem> OrderItems=>Set<OrderItem>(); public DbSet<OrderStatusHistory> OrderStatusHistory=>Set<OrderStatusHistory>(); public DbSet<StockMovement> StockMovements=>Set<StockMovement>(); public DbSet<Payment> Payments=>Set<Payment>(); public DbSet<PaymentTransaction> PaymentTransactions=>Set<PaymentTransaction>(); public DbSet<Notification> Notifications=>Set<Notification>(); public DbSet<ProductReview> ProductReviews=>Set<ProductReview>(); public DbSet<ReturnRequest> ReturnRequests=>Set<ReturnRequest>(); public DbSet<ReturnRequestItem> ReturnRequestItems=>Set<ReturnRequestItem>(); public DbSet<ReturnStatusHistory> ReturnStatusHistory=>Set<ReturnStatusHistory>(); public DbSet<Permission> Permissions=>Set<Permission>(); public DbSet<RolePermission> RolePermissions=>Set<RolePermission>(); public DbSet<UserSession> UserSessions=>Set<UserSession>(); public DbSet<RefreshToken> RefreshTokens=>Set<RefreshToken>(); public DbSet<LoginAttempt> LoginAttempts=>Set<LoginAttempt>(); public DbSet<SecurityEvent> SecurityEvents=>Set<SecurityEvent>(); public DbSet<AuditLog> AuditLogs=>Set<AuditLog>(); public DbSet<AppSetting> AppSettings=>Set<AppSetting>();
 IQueryable<Category> IApplicationDbContext.Categories=>Categories; IQueryable<Product> IApplicationDbContext.Products=>Products; IQueryable<ProductVariant> IApplicationDbContext.ProductVariants=>ProductVariants; IQueryable<Inventory> IApplicationDbContext.Inventories=>Inventories; IQueryable<Cart> IApplicationDbContext.Carts=>Carts; IQueryable<Address> IApplicationDbContext.Addresses=>Addresses; IQueryable<Order> IApplicationDbContext.Orders=>Orders; IQueryable<Coupon> IApplicationDbContext.Coupons=>Coupons; IQueryable<StockMovement> IApplicationDbContext.StockMovements=>StockMovements; IQueryable<UserSession> IApplicationDbContext.UserSessions=>UserSessions; IQueryable<RefreshToken> IApplicationDbContext.RefreshTokens=>RefreshTokens; IQueryable<SecurityEvent> IApplicationDbContext.SecurityEvents=>SecurityEvents; IQueryable<AuditLog> IApplicationDbContext.AuditLogs=>AuditLogs;
 void IApplicationDbContext.Add<T>(T entity)=>Set<T>().Add(entity); void IApplicationDbContext.Remove<T>(T entity)=>Set<T>().Remove(entity);
 protected override void OnModelCreating(ModelBuilder b)
 {
     base.OnModelCreating(b);
     b.ApplyConfigurationsFromAssembly(typeof(MarinaDbContext).Assembly);
     // Domain entities allocate their identifiers in Entity's constructor. A new
     // child added to a tracked collection must be INSERTed, not inferred existing.
     foreach (var entity in b.Model.GetEntityTypes().Where(x => typeof(Marina.Domain.Common.Entity).IsAssignableFrom(x.ClrType)))
         b.Entity(entity.ClrType).Property(nameof(Marina.Domain.Common.Entity.Id)).ValueGeneratedNever();
 }
 public override Task<int> SaveChangesAsync(CancellationToken ct=default){var now=DateTime.UtcNow;foreach(var entry in ChangeTracker.Entries<Marina.Domain.Common.Entity>()){if(entry.State==EntityState.Added)entry.Entity.CreatedUtc=now;if(entry.State==EntityState.Modified)entry.Entity.UpdatedUtc=now;}return base.SaveChangesAsync(ct);}
}
